#include "ge_runtime.hpp"
#include "ge_sprites_reference.hpp"
#include <bit>
#include <cstring>
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>
namespace {
unsigned assertions{};
void require(bool value,const std::string &why){++assertions;if(!value)throw std::runtime_error(why);}
using Bytes=std::vector<std::uint8_t>;
using Observer=chili::PerformanceTelemetry;
struct Input{std::array<unsigned,256> r{};unsigned v=0x08804000,data=0x60002;Bytes vertices,vram;};
Bytes read(const std::filesystem::path &p,std::size_t size){std::ifstream f(p,std::ios::binary);require(bool(f),"fixture absent: "+p.string());f.seekg(0,std::ios::end);require(f.tellg()==static_cast<std::streamoff>(size),"fixture length changed");f.seekg(0);Bytes b(size);f.read(reinterpret_cast<char*>(b.data()),static_cast<std::streamsize>(size));require(bool(f),"fixture read failed");return b;}
bool cpu_equal(const psprecomp::AllegrexContext &a,const psprecomp::AllegrexContext &b){return a.gpr==b.gpr&&a.hi==b.hi&&a.lo==b.lo&&a.pc==b.pc&&a.fcr31==b.fcr31&&a.vfpu_ctrl==b.vfpu_ctrl&&std::memcmp(a.fpr.data(),b.fpr.data(),sizeof(a.fpr))==0&&std::memcmp(a.vfpu.data(),b.vfpu.data(),sizeof(a.vfpu))==0;}
void seed(psprecomp::AllegrexContext &c){for(unsigned n=1;n<32;++n)c.gpr[n]=0x90000000+n;c.gpr[28]=0x08D9ABCD;c.gpr[29]=0x09FE8810;c.gpr[31]=0x08844364;c.pc=0x08D98A58;c.hi=0x12345678;c.lo=0x87654321;c.fcr31=0x13579BDF;for(unsigned n=0;n<32;++n)c.fpr[n]=std::bit_cast<float>(0x7FC10000+n);for(unsigned n=0;n<128;++n)c.vfpu[n]=std::bit_cast<float>(0xFFC10000+n);for(unsigned n=0;n<16;++n)c.vfpu_ctrl[n]=0xE4000000+n;}
void load(psprecomp::Runtime &rt,const Input &in){rt.memory().copy_in(0x04000000,in.vram);if(rt.memory().contains(in.v,in.vertices.size()))rt.memory().copy_in(in.v,in.vertices);seed(rt.cpu());}
void vertex(Input &in,unsigned n,unsigned u,unsigned v,int x,int y,unsigned z=65535){auto h=[&](unsigned off,unsigned value){in.vertices[off]=std::uint8_t(value);in.vertices[off+1]=std::uint8_t(value>>8);};h(n*10,u);h(n*10+2,v);h(n*10+4,std::uint16_t(x));h(n*10+6,std::uint16_t(y));h(n*10+8,z);}
Input synthetic(bool horizontal,bool flip_x=false,bool flip_y=false,unsigned mirror=0){Input in;in.vertices.resize(20);in.vram.resize(psprecomp::GuestMemory::kVramSize);for(std::size_t n=0;n<in.vram.size();++n)in.vram[n]=std::uint8_t((n*37+n/97+19)&255);
    in.r[0x12]=0x800102;in.r[0x1E]=1;in.r[0xC3]=in.r[0xC9]=in.r[0xD2]=3;in.r[0xC6]=0x101;in.r[0x9D]=8;in.r[0xA0]=mirror;in.r[0xA8]=0x040008;in.r[0xB8]=0x303;in.r[0xD5]=in.r[0x16]=7|(7<<10);in.r[0x55]=0xFFFFFF;in.r[0x58]=255;in.r[0xE7]=1;
    const int x0=horizontal?4:0,y0=horizontal?0:4;vertex(in,0,flip_x?4:0,flip_y?4:0,flip_x?x0+4:x0,flip_y?y0+4:y0);vertex(in,1,flip_x?0:4,flip_y?0:4,flip_x?x0:x0+4,flip_y?y0:y0+4);return in;}
Bytes snapshot_reference(const Input &in){psprecomp::Runtime rt;load(rt,in);auto regs=in.r;const unsigned tex=(regs[0xA0]&0xFFFFF0)|((regs[0xA8]<<8)&0x0F000000);const unsigned bytes=(regs[0xA8]&0x7FF)*4u*(1u<<((regs[0xB8]>>8)&15));Bytes source(bytes);rt.memory().copy_out(tex,source);
    constexpr unsigned relocated=0x08900000;rt.memory().copy_in(relocated,source);regs[0xA0]=relocated&0xFFFFFF;regs[0xA8]=(regs[0xA8]&0x7FF)|((relocated>>8)&0x0F0000);
    const auto ram=rt.memory().bytes();const auto cpu=rt.cpu();unsigned cursor=0xDEADBEEF;std::string error;
    require(chili_zero_tap_baseline::render_ge_sprites(rt.memory(),regs,in.v,in.data,cursor,error),"nonoverlap unchanged-source reference failed: "+error);
    require(cursor==in.v+in.vertices.size()&&rt.memory().bytes()==ram&&cpu_equal(cpu,rt.cpu()),"snapshot reference changed source/context/cursor");return rt.memory().vram_bytes();}
void original_rejects(const Input &in){psprecomp::Runtime rt;load(rt,in);const auto ram=rt.memory().bytes();const auto cpu=rt.cpu();unsigned cursor=0xDEADBEEF;std::string error;
    require(!chili_zero_tap_baseline::render_ge_sprites(rt.memory(),in.r,in.v,in.data,cursor,error)&&error=="sprite feedback has a read-after-write dependency","original guard did not reject zero-tap overlap");require(cursor==0xDEADBEEF&&rt.memory().vram_bytes()==in.vram&&rt.memory().bytes()==ram&&cpu_equal(cpu,rt.cpu()),"original guard rejection was not atomic");}
void direct(const Input &in,const Bytes *expected,bool enabled,const std::string &why){std::ostringstream output;Observer observer(output);psprecomp::Runtime rt;load(rt,in);const auto ram=rt.memory().bytes();const auto cpu=rt.cpu();unsigned cursor=0xDEADBEEF;std::string error;
    const bool good=chili::render_ge_sprites(rt.memory(),in.r,in.v,in.data,cursor,error,nullptr,enabled?&observer:nullptr);
    require(good==bool(expected),why+": direct result: "+error);require(rt.memory().vram_bytes()==(expected?*expected:in.vram),why+": complete2MiB output/atomicity");require(cursor==(expected?in.v+in.vertices.size():0xDEADBEEF),why+": cursor publication");require(rt.memory().bytes()==ram&&cpu_equal(cpu,rt.cpu()),why+": source RAM/bitwise full CPU");require(output.str().empty(),"observer emitted inside renderer");
    if(enabled){require(observer.counters()[Observer::TexturedSpriteAttempts]==1,"textured helper attempt missing");if(!expected)require(observer.counters()[Observer::TexturedSpriteRasterWallNs]==0,"failed guard charged raster");}else require(observer.counters()==Observer::Counters{},"null observer updated counters");}
void streamed(const Input &in,const Bytes *expected,bool enabled,const std::string &why){std::ostringstream output;Observer observer(output);psprecomp::Runtime rt;load(rt,in);chili::ThreadRuntime threads(rt);chili::GeRuntime ge(rt,&threads,0,nullptr,enabled?&observer:nullptr);ge.commands=in.r;
    constexpr unsigned list=0x09E00000;rt.memory().store32(list,0x10000000|((in.v>>8)&0xFF0000));rt.memory().store32(list+4,0x01000000|(in.v&0xFFFFFF));rt.memory().store32(list+8,0x04000000|in.data);rt.memory().store32(list+12,0x0F00BEEF);rt.memory().store32(list+16,0x0C000000);rt.cpu().gpr[4]=list;rt.cpu().gpr[5]=0;rt.cpu().gpr[6]=0xFFFFFFFF;rt.cpu().gpr[7]=0;auto cpu=rt.cpu();if(expected)cpu.gpr[2]=1;const auto ram=rt.memory().bytes();const auto time=threads.now_us(),generation=psprecomp::runtime_thread_switch_generation();const auto uid=psprecomp::runtime_thread_uid();
    rt.invoke_import("sceGe_user",0xAB49E76Au,rt.cpu());require(rt.stopped()==!bool(expected),why+": runtime completion state");require(ge.completed.contains(1)==bool(expected),why+": failed draw acknowledged");require(ge.vertex_address==(expected?in.v+in.vertices.size():in.v),why+": native cursor advanced on failure");require(ge.commands[4]==(expected?(0x04000000|in.data):in.r[4]),why+": PRIM published on failure");require(rt.memory().vram_bytes()==(expected?*expected:in.vram)&&rt.memory().bytes()==ram&&cpu_equal(cpu,rt.cpu()),why+": HLE VRAM/source/CPU parity");require(threads.now_us()==time&&uid==psprecomp::runtime_thread_uid()&&generation==psprecomp::runtime_thread_switch_generation(),why+": guest scheduler changed");require(output.str().empty(),"observer emitted inside HLE");if(enabled)require(observer.counters()[Observer::DrawSuccesses]==unsigned(bool(expected))&&observer.counters()[Observer::DrawFailures]==unsigned(!expected),"whole-draw success/failure semantics changed");else require(observer.counters()==Observer::Counters{},"null HLE observer updated counters");}
void accept(const Input &in,const Bytes &expected,const std::string &why,bool old_reject=true){if(old_reject)original_rejects(in);for(bool enabled:{false,true}){direct(in,&expected,enabled,why);streamed(in,&expected,enabled,why);}}
void reject(const Input &in,const std::string &why,bool runtime=true){for(bool enabled:{false,true}){direct(in,nullptr,enabled,why);if(runtime)streamed(in,nullptr,enabled,why);}}
void captured(const std::filesystem::path &prefix,const std::filesystem::path &oracle){Input in;std::ifstream f(prefix.string()+".txt");require(bool(f),"actual metadata absent");std::string line;while(std::getline(f,line)){std::istringstream words(line);std::string kind;words>>kind;if(kind=="reg"){unsigned n{},v{};words>>std::hex>>n>>v;require(bool(words)&&n<256,"invalid captured register");in.r[n]=v;}else if(kind.starts_with("primitive=")){in.data=unsigned(std::stoul(kind.substr(10),nullptr,16));std::string address;words>>address;require(address.starts_with("vertices="),"actual VADDR absent");in.v=unsigned(std::stoul(address.substr(9),nullptr,16));}}
    require(in.v==0x0994D1D8&&in.data==0x60002&&(in.r[0x12]&0xFFFFFF)==0x800102,"actual draw shape changed");in.vertices=read(prefix.string()+"_vertices.bin",20);in.vram=read(prefix.string()+"_vram.bin",psprecomp::GuestMemory::kVramSize);const auto expected=read(oracle,psprecomp::GuestMemory::kVramSize);
    require(snapshot_reference(in)==expected,"nonoverlap baseline differs from independent all-fragment RGB oracle");for(unsigned y=68;y<136;++y)for(unsigned x=0;x<120;++x){const double u=(x+0.5)*120.0/120.0,v=(y+0.5-68.0)*68.0/68.0;require(u-0.5-std::floor(u-0.5)==0&&v-0.5-std::floor(v-0.5)==0,"captured current double-order fraction not exactly zero");}
    unsigned changed{};for(std::size_t n=0;n<in.vram.size();++n)if(in.vram[n]!=expected[n]){const auto off=n-0x88000;require(n>=0x88000&&off%4<3&&(off/4)%512<120&&off/(512*4)>=68&&off/(512*4)<136,"oracle wrote alpha/outside rectangle");++changed;}require(changed==24480,"actual RGB changed-byte count differs");accept(in,expected,"actual8160 pixels");std::cout<<"PASS Actual20-byte PRIM: baseline atomic rejection; candidate null/enabled/direct/realGE exact independent2MiB oracle, fullCPU/source/cursor/UID/time\n";}
void zero_neighbors(){unsigned cases{};for(bool horizontal:{false,true})for(bool fx:{false,true})for(bool fy:{false,true})for(unsigned mirror:{0u,0x200000u,0x400000u}){auto in=synthetic(horizontal,fx,fy,mirror);const auto expected=snapshot_reference(in);accept(in,expected,"zero neighbor/flipped/mirror");++cases;}
    for(unsigned mask:{0u,0x0F55AAu,0xFFFFFFu})for(unsigned alpha:{0u,0x55u,255u}){auto in=synthetic(false);in.r[0x21]=1;in.r[0xDF]=0xA;in.r[0xE0]=0xFFFFFF;in.r[0xE8]=mask;in.r[0xE9]=alpha;const auto expected=snapshot_reference(in);accept(in,expected,"partial/full masks",mask!=0xFFFFFFu||alpha!=255u);++cases;}
    std::cout<<"PASS "<<cases<<" horizontal/vertical zero neighbors, independent source snapshot, reversed axes, physicalmirror aliases, RGB/alpha masks\n";}
void genuine_dependencies(){for(bool horizontal:{false,true})for(bool tiny:{false,true}){auto in=synthetic(horizontal);if(horizontal){vertex(in,0,0,0,4,0);vertex(in,1,tiny?32764:5,4,tiny?32767:8,4);}else{vertex(in,0,0,0,0,4);vertex(in,1,4,tiny?32764:5,4,tiny?32767:8);}
        if(tiny){const double fraction=3.5*32764.0/32763.0-0.5-3.0;require(fraction>0&&fraction<0.00011,"tiny positive fixture not small/nonzero");}reject(in,tiny?"tiny positive fractional dependency":"positive fractional dependency");}
    auto nearest=synthetic(false);nearest.r[0xC6]=0;vertex(nearest,0,0,4,0,4);vertex(nearest,1,4,8,4,8); // current-pixel self reads, no earlier dependency
    accept(nearest,snapshot_reference(nearest),"nearest unchanged path",false);
    auto backward=synthetic(false);backward.r[0xC6]=0;vertex(backward,0,0,3,0,4);vertex(backward,1,4,7,4,8);reject(backward,"nearest positive earlier-row dependency");
    auto depth=synthetic(false);depth.r[0x9C]=0x10000;depth.r[0x9F]=8;depth.r[0xE7]=0;depth.r[0xE8]=0xFFFFFF;depth.r[0xE9]=255;vertex(depth,0,0,0,0,0);vertex(depth,1,4,0,4,4);reject(depth,"depth-write-induced weighted dependency with all color masked");
    auto masked=synthetic(false);vertex(masked,1,4,5,4,8);masked.r[0xE8]=0xFFFFFF;masked.r[0xE9]=255;accept(masked,snapshot_reference(masked),"no color/depth writes means no dependency",false);
    std::cout<<"PASS Positive horizontal/vertical fractions, tiny nonzero weights, color/depth write dependencies stay atomic; nearest and fully masked no-write semantics retained\n";}
void malformed(){for(unsigned n=0;n<6;++n){auto in=synthetic(false);if(n==0)in.r[0x12]=0;if(n==1)in.data=0x60001;if(n==2)in.r[0xD2]=2;if(n==3)in.r[0xC6]=2;if(n==4)in.r[0xC3]=8;if(n==5)in.v=0x09FFFFF6;reject(in,"malformed/count/bounds");}std::cout<<"PASS Malformed format/count/filter/target/texture/source bounds preserve VRAM/source/CPU/cursors\n";}
}
int main(int argc,char **argv){try{require(argc==3,"Usage: ge_zero_tap_feedback_test <actual capture prefix> <independent expected VRAM>");captured(argv[1],argv[2]);zero_neighbors();genuine_dependencies();malformed();std::cout<<"PASS "<<assertions<<" contributing-tap feedback assertions; positive-weight PSP cache semantics remain strict, no hardware/FPS/gameplay claim\n";}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
